/// Serializable observer reference
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum ObserverKind {
    ArtifactBundle,
    Trace { layer_name: String },
    FileSystem { base_path: String },
}

impl ObserverKind {
    pub fn instantiate(&self) -> Box<dyn Observer> {
        match self {
            ObserverKind::ArtifactBundle => Box::new(ArtifactBundleObserver),
