use crate::formal::projection::{Extractor, ArtifactSpace};

impl Extractor<InferredSpecification> for RustExtractor {
    fn extract(&self, artifact: &ArtifactSpace) -> Result<Vec<InferredSpecification>, String> {
        let content = artifact.as_text()?;
        let mut specs = Vec::new();

        // Use existing extraction methods (adapted to work with string content)
        specs.extend(Self::extract_from_function_names_str(&content, &artifact.source)?);
        specs.extend(Self::extract_from_assertions_str(&content, &artifact.source)?);
        specs.extend(Self::extract_from_tests_str(&content, &artifact.source)?);
        specs.extend(Self::extract_from_docs_str(&content, &artifact.source)?);
        specs.extend(Self::extract_from_panics_str(&content, &artifact.source)?);

        Ok(specs)
    }
}

// Keep old API for backward compatibility
impl RustExtractor {
    pub fn extract(file_path: &Path) -> Result<Vec<InferredSpecification>, String> {
        let artifact = ArtifactSpace::from_file(
            file_path.to_path_buf(),
            ArtifactKind::SourceCode,
        );

        let extractor = RustExtractor;
        extractor.extract(&artifact)
    }
