**projection/root_space.rs**

Define Ω (root space) following the 3-layer pattern (ID/ProofData/Metadata):

```rust
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use uuid::Uuid;

/// Root space Ω: foundational space from which projections are derived
/// Following paper §2.5, supports Trace or ArtifactBundle instantiation
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RootSpace {
    // Layer 1: Identifier
    pub id: RootSpaceId,

    // Layer 2: ProofData (optional - not used for root space)
    // Root space is not a proof target, so no proof_data

    // Layer 3: Metadata (stores all organizational info)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub meta: Option<RootSpaceMetadata>,
}

/// Root space identifier
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct RootSpaceId(String);

impl RootSpaceId {
    pub fn new() -> Self {
        Self(Uuid::new_v4().to_string())
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

/// Root space metadata (Layer 3)
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct RootSpaceMetadata {
    #[serde(flatten)]
    inner: HashMap<String, String>,
}

impl RootSpaceMetadata {
    pub fn new() -> Self {
        Self { inner: HashMap::new() }
    }

    /// Get root space kind (trace or artifact_bundle)
    pub fn kind(&self) -> Option<RootSpaceKind> {
        self.inner.get("kind").and_then(|k| match k.as_str() {
            "trace" => Some(RootSpaceKind::Trace),
            "artifact_bundle" => Some(RootSpaceKind::ArtifactBundle),
            _ => None,
        })
    }

    pub fn set_kind(&mut self, kind: RootSpaceKind) {
        self.inner.insert("kind".to_string(), kind.to_string());
    }

    /// Snapshot time (for artifact bundles)
    pub fn snapshot_time(&self) -> Option<&String> {
        self.inner.get("snapshot_time")
    }

    pub fn set_snapshot_time(&mut self, time: String) {
        self.inner.insert("snapshot_time".to_string(), time);
    }

    /// Version/commit (for reproducibility)
    pub fn version(&self) -> Option<&String> {
        self.inner.get("version")
    }

    pub fn set_version(&mut self, version: String) {
        self.inner.insert("version".to_string(), version);
    }

    /// Generic getter
    pub fn get(&self, key: &str) -> Option<&String> {
        self.inner.get(key)
    }

    /// Generic setter
    pub fn insert(&mut self, key: String, value: String) {
        self.inner.insert(key, value);
    }
}

/// Root space kind (stored in metadata)
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RootSpaceKind {
    /// Ω_trace: Behavioral trace
    Trace,
    /// Ω_art: Artifact bundle (PoC choice)
    ArtifactBundle,
}

impl std::fmt::Display for RootSpaceKind {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            RootSpaceKind::Trace => write!(f, "trace"),
            RootSpaceKind::ArtifactBundle => write!(f, "artifact_bundle"),
        }
    }
}

impl RootSpace {
    /// Create new root space with artifact bundle kind
    pub fn new_artifact_bundle() -> Self {
        let mut meta = RootSpaceMetadata::new();
        meta.set_kind(RootSpaceKind::ArtifactBundle);

        Self {
            id: RootSpaceId::new(),
            meta: Some(meta),
        }
    }

    /// Create new root space with trace kind
    pub fn new_trace() -> Self {
        let mut meta = RootSpaceMetadata::new();
        meta.set_kind(RootSpaceKind::Trace);

        Self {
            id: RootSpaceId::new(),
            meta: Some(meta),
        }
    }
}
