    if let Some(meta) = root.meta.as_mut() {
        meta.set_snapshot_time("2025-01-01".to_string());
        meta.set_version("abc123".to_string());
        // Register artifact path for U3 (code layer)
        meta.insert("artifact_U3_path".to_string(), "src/lib.rs".to_string());
    }

    // Create projection strategy
    let strategy = ProjectionStrategy::ASTExtraction {
        language: "rust".to_string(),
        observer: ObserverKind::ArtifactBundle,
        extractor_config: HashMap::new(),
    };

    // Create transform
    let transform = TransformFunction::new_with_projection(
        UniverseId::projection(3, "code".to_string(), String::new()).unwrap(),
        "Extract from code".to_string(),
        strategy,
    );

    // Execute
    let model = UDAFModel::new();
    let graph = SpecRepository::new();
    let specs = model.execute_transform(&transform, &graph, &root).unwrap();

    // Verify composition worked
    assert!(!specs.is_empty());
}
