/// Observer: obs_i (Omega -> Option Gamma_i)
///
/// An observer examines a root space (Omega) and, if the root space matches
/// the observer's expected kind, extracts an artifact space (Gamma_i) from it.
///
/// This is the first half of the projection composition:
///   proj_i = obs_i >> extract_i
///
/// Each observer is specialized for a particular root space kind:
/// - ArtifactBundleObserver: observes artifact bundle root spaces
/// - TraceObserver: observes behavioral trace root spaces
/// - FileSystemObserver: observes file system root spaces directly
use crate::formal::projection::{RootSpace, RootSpaceKind, ArtifactSpace, ArtifactKind};

/// Observer trait: examines a root space and produces an artifact space.
///
/// Implements obs_i: Omega -> Option<Gamma_i>
/// Returns None when the root space kind does not match the observer's expectation.
pub trait Observer {
    /// Attempt to observe an artifact space from the given root space.
    ///
    /// Returns `Some(ArtifactSpace)` if the root space kind matches and
    /// artifact information can be extracted from metadata.
    /// Returns `None` if the root space kind does not match.
    fn observe(&self, root: &RootSpace) -> Option<ArtifactSpace>;

    /// The kind of artifact this observer produces.
    fn artifact_kind(&self) -> ArtifactKind;
}

/// Observer for artifact bundle root spaces.
///
/// Expects `RootSpaceKind::ArtifactBundle` and extracts artifact information
/// from the root space metadata fields: "content_value" and "source".
pub struct ArtifactBundleObserver {
    expected_artifact_kind: ArtifactKind,
}

impl ArtifactBundleObserver {
    pub fn new(expected_artifact_kind: ArtifactKind) -> Self {
        Self { expected_artifact_kind }
    }
}

impl Observer for ArtifactBundleObserver {
    fn observe(&self, root: &RootSpace) -> Option<ArtifactSpace> {
        if root.kind() != Some(RootSpaceKind::ArtifactBundle) {
            return None;
        }

/// Projection: The composition of observation and extraction
///
/// proj_i = obs_i >> extract_i
///
/// A projection takes a RootSpace, observes it through a specific layer lens
/// to produce an ArtifactSpace, then extracts typed intermediate representations.
///
/// This implements the core composition from paper §2.6:
///   Γ_root →[obs_i]→ Γ_i →[extract_i]→ β_i
///
/// Where:
///   - obs_i: RootSpace → ArtifactSpace (layer-specific observation)
///   - extract_i: ArtifactSpace → Vec<T> (typed extraction from artifacts)
///   - proj_i: the composition obs_i >> extract_i
use crate::formal::projection::{ArtifactSpace, Observer, RootSpace};
use crate::formal::universe::UniverseId;

/// Extractor trait: Γ_i → Option<β_i>
///
/// Extracts typed intermediate representations from an artifact space.
/// Each extractor is specialized for a particular output type T (the β_i).
///
/// Returns a Vec<T> because a single artifact space may yield multiple
/// extracted items (e.g., multiple spec fragments from a code file).
pub trait Extractor<T> {
    /// Extract typed representations from an artifact space.
    ///
    /// Given an observed artifact space Γ_i, produces a vector of
    /// extracted items of type T. Returns an empty Vec if no items
    /// can be extracted (rather than failing).
    fn extract(&self, artifact: &ArtifactSpace) -> Vec<T>;
}

/// Projection: composes an Observer and an Extractor into a single operation.
///
/// ```text
/// RootSpace →[observer]→ ArtifactSpace →[extractor]→ Vec<T>
/// ```
///
/// The target_layer determines which universe layer the observer focuses on.
pub struct Projection<O, E> {
    /// The observer that produces an ArtifactSpace from a RootSpace
    pub observer: O,

    /// The extractor that produces typed output from an ArtifactSpace
    pub extractor: E,

    /// The target universe layer for observation (e.g., U1, U2, U3)
    pub target_layer: UniverseId,
}

